static void bind(const ksn_mesh_pixel_snapshot*s){size_t at=0;unsigned ri=0,total=0;memset(source,255,sizeof source);while(at<s->mesh.packets.size){assert(ri<54);co_view*v=views+ri;assert(co_read(s->mesh.packets.data+at,s->mesh.packets.size-at,v));assert(v->node==ri+1);unsigned first=u16(identity_bytes+2*(v->node-1)),end=u16(identity_bytes+2*v->node);assert(end-first==v->triangle_count);uint64_t matched=0;for(unsigned f=0;f<v->triangle_count;f++){uint8_t ix[3];bool back;assert(co_triangle_at(v,f,ix)&&co_triangle_side(v,f,&back));unsigned found=0;for(unsigned k=first;k<end;k++){const uint8_t*e=identity_bytes+110+5*k;unsigned equal=0;for(unsigned j=0;j<3;j++)for(unsigned l=0;l<3;l++)equal+=ix[j]==e[l];if(equal==3){assert(!(matched&(UINT64_C(1)<<(k-first))));matched|=UINT64_C(1)<<(k-first);unsigned a=((ix[0]>ix[1])+(ix[0]>ix[2])+(ix[1]>ix[2]))&1,b=((e[0]>e[1])+(e[0]>e[2])+(e[1]>e[2]))&1;assert((a^b)==back);source[v->node][f]=u16(e+3);found++;}}assert(found==1);}total+=v->triangle_count;ri++;at+=v->size;}assert(ri==54&&total==1564&&at==s->mesh.packets.size);}
static void event(FILE*out,unsigned phase,unsigned p,unsigned ri,unsigned face,double dx,double dy,float depth){const co_view*v=views+ri;uint8_t ix[3];co_vertex q[3];co_pixel_vertex f[3];bool back;assert(co_triangle_at(v,face,ix)&&co_triangle_side(v,face,&back));for(unsigned j=0;j<3;j++)assert(co_vertex_at_side(v,ix[j],back,q+j)&&co_pixel_vertex_at(v,ix[j],f+j));double area=((double)q[1].x-q[0].x)*((double)q[2].y-q[0].y)-((double)q[1].y-q[0].y)*((double)q[2].x-q[0].x),inv=1/area,b[3];gouraud_edge e[3]={gouraud_make_edge(q+1,q+2),gouraud_make_edge(q+2,q),gouraud_make_edge(q,q+1)};for(unsigned k=0;k<3;k++)b[k]=(e[k].sign*(e[k].a*((p%240)+dx)+e[k].b*((p/240)+dy)+e[k].c))*inv;bool second=b[0]*q[0].mask+b[1]*q[1].mask+b[2]*q[2].mask>=0;double w[3]={0},n[3]={0},rho[3];float dec[3][3];for(unsigned j=0;j<3;j++){uint16_t code=second?q[j].color_b:q[j].color_a;const int16_t*nc=back?f[j].normal_back:f[j].normal_front;dec[j][0]=ayatsuri_srgb_decode((code>>11)/31.0f);dec[j][1]=ayatsuri_srgb_decode(((code>>5)&63)/63.0f);dec[j][2]=ayatsuri_srgb_decode((code&31)/31.0f);for(unsigned k=0;k<3;k++){w[k]+=b[j]*f[j].world[k];n[k]+=b[j]*(nc[k]/32767.0);}}if(phase){assert(ksn_aa_rho_affine(dec,b,rho));}else{for(unsigned k=0;k<3;k++){rho[k]=0;for(unsigned j=0;j<3;j++)rho[k]+=b[j]*dec[j][k];rho[k]=fmax(0,fmin(1,rho[k]));}}fprintf(out,"{\"phase\":%u,\"x\":%u,\"y\":%u,\"recordOffset\":%u,\"node\":%u,\"face\":%u,\"sourceId\":%u,\"back\":%s,\"depth\":%.9g,\"P\":[%.17g,%.17g,%.17g],\"Ns\":[%.17g,%.17g,%.17g],\"rho\":[%.17g,%.17g,%.17g]}\n",phase,p%240,p/240,(unsigned)(v->data-storage-416),v->node,face,source[v->node][face],back?"true":"false",depth,w[0]/38,-w[2]/38,-w[1]/38,n[0],-n[2],-n[1],rho[0],rho[1],rho[2]);}
static void coverage(unsigned phase,FILE*events){double dx=phase?((phase-1)&1?.25:-.25):0,dy=phase?((phase-1)&2?.25:-.25):0;for(unsigned i=0;i<N;i++){depths[phase][i]=-INFINITY;records[phase][i]=65535;faces[phase][i]=255;}
 for(unsigned y=0;y<135;y+=8){unsigned rows=135-y;if(rows>8)rows=8;for(unsigned ri=0;ri<54;ri++){const co_view*v=views+ri;for(unsigned face=0;face<v->triangle_count;face++){uint8_t ix[3];co_vertex q[3];bool back;assert(co_triangle_at(v,face,ix)&&co_triangle_side(v,face,&back));for(unsigned j=0;j<3;j++)assert(co_vertex_at_side(v,ix[j],back,q+j));double area=((double)q[1].x-q[0].x)*((double)q[2].y-q[0].y)-((double)q[1].y-q[0].y)*((double)q[2].x-q[0].x),inv=1/area;assert(isfinite(area)&&area>1e-5);gouraud_edge e[3]={gouraud_make_edge(q+1,q+2),gouraud_make_edge(q+2,q),gouraud_make_edge(q,q+1)};int l=(int)ceil(fmin(q[0].x,fmin(q[1].x,q[2].x))-dx),r=(int)floor(fmax(q[0].x,fmax(q[1].x,q[2].x))-dx),t=(int)ceil(fmin(q[0].y,fmin(q[1].y,q[2].y))-dy),bot=(int)floor(fmax(q[0].y,fmax(q[1].y,q[2].y))-dy);if(l<0)l=0;if(r>239)r=239;if(t<(int)y)t=(int)y;if(bot>=(int)(y+rows))bot=(int)(y+rows)-1;if(l<=r&&t<=bot)band_boxes[phase]++;for(int yy=t;yy<=bot;yy++)for(int x=l;x<=r;x++){bbox[phase]++;unsigned p=yy*240+x;if(phase&&!mask[p])continue;tests[phase]++;double b[3];bool in=true;for(unsigned k=0;k<3;k++){b[k]=phase?e[k].sign*(e[k].a*(x+dx)+e[k].b*(yy+dy)+e[k].c):gouraud_edge_value(e+k,x,yy);if(b[k]<0||(b[k]==0&&!e[k].closed))in=false;}if(!in)continue;for(unsigned k=0;k<3;k++)b[k]*=inv;float d=(float)(b[0]*q[0].depth+b[1]*q[1].depth+b[2]*q[2].depth);assert(isfinite(d));if(d<=depths[phase][p])continue;depths[phase][p]=d;records[phase][p]=ri;faces[phase][p]=face;updates[phase]++;if(!phase){center[p]=source[v->node][face];center_updates++;event(events,phase,p,ri,face,dx,dy,d);}}}}}
 for(unsigned p=0;p<N;p++)if(records[phase][p]!=65535){hits[phase]++;if(phase)event(events,phase,p,records[phase][p],faces[phase][p],dx,dy,depths[phase][p]);}}
int main(int argc,char**argv){assert(argc==20);char reserve[4096];assert(snprintf(reserve,sizeof reserve,"%s.reservation",argv[2])<(int)sizeof reserve);assert(mkdir(reserve,0700)==0);FILE*f=fopen(argv[1],"rb");assert(f);fseek(f,0,SEEK_END);long n=ftell(f);assert(n>0&&n<=1048576);rewind(f);uint8_t*data=malloc(n);assert(data&&fread(data,1,n,f)==(size_t)n);fclose(f);ayatsuri_model m;assert(!ayatsuri_model_open(data,n,&m));assert(m.node_count==55);float cam[9],light[6];for(unsigned k=0;k<9;k++)cam[k]=strtof(argv[4+k],NULL);for(unsigned k=0;k<6;k++)light[k]=strtof(argv[13+k],NULL);FoxDiskScene ds;assert(disk(argv[3],&ds));int owner;ayatsuri_model_instance ins;model_arena_owner*arena=model_arena_owner_create(&m,&owner,1,&ins,malloc,free);assert(arena);/* Deliberately no physical scene on model: discarded legacy vertex colors only. */assert(!ayatsuri_model_instance_evaluate(&ins,&owner,1,cam,light));ksn_mesh_pixel_snapshot s;assert(ksn_mesh_pixel_begin(&s,storage,sizeof storage,&ds,8000000));uint32_t cursor=0;ayatsuri_model_packet packet;ayatsuri_model_status status;while((status=ayatsuri_model_instance_next(&ins,&owner,1,&cursor,&packet))==AYATSURI_MODEL_OK){assert(packet.kind==5);ayatsuri_model_pixel_mesh_view raw;assert(!ayatsuri_model_instance_pixel_mesh_view(&ins,&owner,1,packet.node_id,ins.mutation_epoch,&raw));ksn_proc_gouraud_patch patch=*raw.patch;uint8_t bits[8];memcpy(bits,raw.back_faces,8);assert(ksn_mesh_pixel_append_normal_pair(&s,&patch,raw.vertices,bits,packet.node_id));}assert(status==AYATSURI_MODEL_DONE);
 double world[1167][3];uint32_t tri[1566][3];unsigned nv=0,nt=0;
 for(unsigned id=1;id<m.node_count;id++){ayatsuri_model_world_mesh_view v;assert(!ayatsuri_model_instance_world_mesh_view(&ins,&owner,1,id,ins.mutation_epoch,&v));assert(nv+v.vertex_count<=1163&&nt+v.triangle_count<=1564);for(unsigned j=0;j<v.vertex_count;j++){world[nv+j][0]=v.world[j][0]/38;world[nv+j][1]=-v.world[j][2]/38;world[nv+j][2]=-v.world[j][1]/38;}for(unsigned j=0;j<v.triangle_count;j++)for(unsigned k=0;k<3;k++)tri[nt+j][k]=nv+v.indices[3*j+k];nv+=v.vertex_count;nt+=v.triangle_count;}assert(nv==1163&&nt==1564);fox_ground_input ground;assert(fox_ground_load(argv[19],&ground));memcpy(world+nv,ground.world,sizeof ground.world);for(unsigned j=0;j<2;j++)for(unsigned k=0;k<3;k++)tri[nt+j][k]=nv+ground.indices[3*j+k];writeout(argv[2],".world-vertices.f64le",world,sizeof world);writeout(argv[2],".world-triangles.u32le",tri,sizeof tri);
 assert(!ayatsuri_model_instance_dispose(&ins,&owner,1));model_arena_owner_release(&arena,free);free(data);bind(&s);writeout(argv[2],".snapshot",storage,416+s.mesh.packets.size);memset(center,255,sizeof center);FILE*events=output(argv[2],".events.jsonl");coverage(0,events);for(unsigned y=0;y<135;y++)for(unsigned x=0;x<240;x++){unsigned p=y*240+x;uint16_t c=center[p],u=y?center[p-240]:65535,l=x?center[p-1]:65535,r=x<239?center[p+1]:65535,d=y<134?center[p+240]:65535;mask[p]=c!=u||c!=l||c!=r||c!=d;if(mask[p]){targets++;covered+=c!=65535;}}for(unsigned q=1;q<5;q++)coverage(q,events);assert(!fclose(events));writeout(argv[2],".targets.u8",mask,sizeof mask);writeout(argv[2],".center-depth.f32le",depths[0],sizeof depths[0]);writeout(argv[2],".center-source.u16le",center,sizeof center);writeout(argv[2],".winner-records.u16le",records,sizeof records);writeout(argv[2],".winner-faces.u8",faces,sizeof faces);writeout(argv[2],".winner-depths.f32le",depths,sizeof depths);f=output(argv[2],".geometry.json");fprintf(f,"{\"snapshotBytes\":%zu,\"snapshotFNV\":\"%016llx\",\"targetFNV\":\"%016llx\",\"legacyCenterReservation\":%u,\"targets\":%u,\"coveredTargets\":%u,\"centerUpdates\":%llu,\"hits\":[",416+s.mesh.packets.size,(unsigned long long)fnv(storage,416+s.mesh.packets.size),(unsigned long long)fnv(mask,sizeof mask),s.mesh.work,targets,covered,(unsigned long long)center_updates);for(unsigned q=0;q<5;q++)fprintf(f,"%s%u",q?",":"",hits[q]);const uint64_t*arrays[]={bbox,tests,updates,band_boxes};const char*names[]={"bboxVisits","testedPoints","winnerUpdates","nonemptyBandBoxes"};for(unsigned j=0;j<4;j++){fprintf(f,"],\"%s\":[",names[j]);for(unsigned q=0;q<5;q++)fprintf(f,"%s%llu",q?",":"",(unsigned long long)arrays[j][q]);}fprintf(f,"],\"physicalShadingExecuted\":false,\"rayQueriesExecuted\":false,\"diagnosticStaticBytes\":%zu}\n",sizeof storage+sizeof mask+sizeof source+sizeof center+sizeof depths+sizeof records+sizeof faces+sizeof views);assert(!fclose(f));return 0;}
